window.FH6DATA={meta:{title:"Forza Horizon 6 Guide",tagline:"An unofficial, source-checked guide to the festival in Japan",description:"Forza Horizon 6 lands in a fictionalised Japan with the biggest map the series has ever built — 550+ cars at launch and 636 in the live roster today. This guide covers the car list, Car Pass and DLC packs, barn finds, treasure cars, the Estate, the interactive Japan map, and a beginner path to Horizon Legend — with sources noted for everything.",lang:"en",developer:"Playground Games (with Turn 10 Studios)",publisher:"Xbox Game Studios",platforms:"Windows · Xbox Series X|S · PlayStation 5 (delayed — date TBC)",released:"May 19, 2026 (Premium early access May 15)",gamePass:"Day one on Game Pass Ultimate & PC Game Pass",ps5Status:"Delayed — date TBC (not expected in 2026)",statusUpdated:"August 31, 2026"},facts:[{k:"Setting",v:"Japan (fictionalised)"},{k:"Released",v:"May 19, 2026"},{k:"Cars at launch",v:"550+ (636 in the live roster as of Aug 13, 2026)"},{k:"Developer",v:"Playground Games"},{k:"Publisher",v:"Xbox Game Studios"},{k:"Platforms",v:"PC · Xbox Series X|S (PS5 delayed — TBC)"},{k:"Game Pass",v:"Day one (Ultimate & PC)"},{k:"Garages",v:"8 (fast-travel)"},{k:"The Eliminator",v:"up to 72 players"}],hero:{eyebrow:"Horizon Japan",title:"Forza Horizon 6",subtitle:"550+ cars, the largest map the series has ever built, and a festival that finally lands in Japan. Here's the straight talk on what to do first, which cars actually matter, and where everything is hidden.",cover:"2025 Toyota GR GT Prototype & 2025 Toyota Land Cruiser",status:[{k:"Out now",v:"May 19, 2026"},{k:"Platforms",v:"Xbox Series X|S & PC"},{k:"Game Pass",v:"Day one (Ultimate & PC)"},{k:"PS5",v:"Delayed — date TBC",flag:!0}]},carCounts:{launch:{n:"550+",source:"Wikipedia [WIKI]",note:"Cars available at the May 19, 2026 launch."},current:{n:636,source:"Official Forza car list (forza.net/fh6cars)",tableUpdated:"August 13, 2026",countedOn:"August 31, 2026",note:"636 rows counted in the official table: 597 base-roster cars plus 39 add-on-labelled cars. Re-count the table after each monthly update and update this figure."},breakdown:[{label:"Base roster",n:597,note:"No add-on label — buyable or earnable in-game."},{label:"Car Pass",n:16,note:"Included with Deluxe/Premium; one car delivered most Thursdays."},{label:"Time Attack Car Pack",n:8,note:"WTAC-style time-attack builds."},{label:"Welcome Pack",n:5,note:"Starter bonus pack."},{label:"Italian Passion Car Pack",n:4,note:"July 14, 2026. Separate $4.99 add-on — NOT part of the Car Pass. Free with Premium Edition/Upgrade."},{label:"VIP",n:3,note:"Forza Edition cars for VIP members."},{label:"Partnership DLC",n:2,note:"Brand-collaboration cars (Peel P50 Trolli, Toyota Sports 800 Fanta)."},{label:"Preorder Bonus",n:1,note:"2017 Ferrari J50."}],packs:[{label:"Car Pass",n:16,how:"Included with Deluxe and Premium editions, or bought separately. Playground delivers one car most Thursdays.",cars:["1957 Ford Thunderbird","1968 Alfa Romeo Autodelta Tipo 33/2 Daytona","1972 Datsun #269 Attacking the Clock Racing 240Z 'All Carbon Hill Climb Beast'","1972 Honda Z GT","1972 Nissan Patrol","1974 Mazda #123 Mad Mike 808 Wagon 'FURSTY'","1983 Nissan Skyline 2000 Turbo RS","1987 Porsche #203 Porsche AG 961","1990 Nissan #12 Skyline GT-R (BNR32 Gr.A) JTC","1998 Nissan Skyline GT-R 40th Anniversary","2003 Aston Martin DB7 GT","2008 Honda Civic Type R (FD2)","2023 Audi R8 Coupé V10 GT RWD","2023 Toyota GR Corolla","2024 Koenigsegg Gemera","2024 Toyota Prius Prime XSE Premium"]},{label:"Time Attack Car Pack",n:8,how:"Paid add-on. Eight WTAC-style time-attack builds.",cars:["1990 Honda #19 101 Motorsport CRX WTAC","1990 Mitsubishi #269 Attacking the Clock Racing Minicab Time Attack","1992 Honda #21 Hardrace/JDMYard Civic WTAC","1993 Nissan #32 Skyline WTAC 'Xtreme GTR'","1995 Toyota J&J Motorsport Supra WTAC","2000 Nissan #36 Dream Project S15 Silvia WTAC","2001 Honda #33 Integra WTAC","2004 Honda #52 Evasive Motorsports S2000 WTAC"]},{label:"Welcome Pack",n:5,how:"Starter pack bundled with some editions.",cars:["2004 Mitsubishi Lancer Evolution VIII MR Welcome Pack","2018 Ferrari FXX-K Evo Welcome Pack","2020 Mercedes-AMG GT Black Series Welcome Pack","2021 BMW M4 Competition Coupé Welcome Pack","2023 Ford F-150 Raptor R Welcome Pack"]},{label:"Italian Passion Car Pack",n:4,how:"Released July 14, 2026. $4.99 standalone; included with the Premium Edition and Premium Upgrade. Deliberately NOT part of the Car Pass.",cars:["1967 Ferrari 275 GTB4 Spider","1990 Alfa Romeo SE 048SP","2021 Alfa Romeo Giulia GTAm","2025 Ferrari F80"]},{label:"VIP",n:3,how:"Forza Edition cars for VIP members.",cars:["1999 Dodge Viper GTS ACR Forza Edition","2019 Toyota Tacoma TRD Pro Forza Edition","2020 Lotus Evija Forza Edition"]},{label:"Partnership DLC",n:2,how:"Brand-collaboration reward cars.",cars:["1962 Peel P50 Trolli Edition","1965 Toyota Sports 800 Fanta Edition"]},{label:"Preorder Bonus",n:1,how:"Pre-order incentive.",cars:["2017 Ferrari J50 Preorder Car"]}]},cars:{intro:"Forza Horizon 6 launches with 550+ cars [WIKI]. The first group lists vehicles confirmed directly by Wikipedia (key-art cover car and the cross-title loyalty rewards). The remaining groups are drawn from community guides (IGN, GamesRadar, Reddit) and are clearly marked as community-sourced.",getWays:[{t:"Autoshow",d:"Buy any car outright with credits. Full price, but you pick exactly the model you want."},{t:"Wheelspins",d:"Free spins from level-ups, story events, and the Festival Playlist — a chance at rare cars and big credit bundles."},{t:"Aftermarket",d:"Green CT icons on the map mark secondhand, fully-tuned cars that cost less than the Autoshow."},{t:"Treasure & Barn",d:"Free hidden cars: photo-clue Treasure Cars and stamp-gated Barn Finds scattered across Japan."}],groups:[{title:"Confirmed vehicles (Wikipedia)",badge:"WIKI",note:"From the official key art and cross-title loyalty rewards [WIKI].",items:[{year:"2025",make:"Toyota",model:"GR GT Prototype",tag:"Cover car",note:"Headline machine on the FH6 key art, with Mount Fuji and Tokyo behind it [WIKI].",disc:"top"},{year:"2025",make:"Toyota",model:"Land Cruiser 250",tag:"Cover car",note:"The second cover car in the reveal key art, alongside the GR GT Prototype [Forza FAQ / WIKI]. The 250-series Land Cruiser.",disc:"offroad"},{year:"2021",make:"Mercedes-AMG",model:"One",tag:"Loyalty (FH5)",note:"Returning reward for playing Forza Horizon 5 [WIKI].",disc:"top"},{year:"2016",make:"Aston Martin",model:"Vulcan",tag:"Loyalty (FH4)",note:"Returning reward for playing Forza Horizon 4 [WIKI].",disc:"top"},{year:"2016",make:"Lamborghini",model:"Centenario LP 770-4",tag:"Loyalty (FH3)",note:"Returning reward for playing Forza Horizon 3 [WIKI].",disc:"top"},{year:"2014",make:"Lamborghini",model:"Huracán LP 610-4",tag:"Loyalty (FH2)",note:"Returning reward for playing Forza Horizon 2 [WIKI].",disc:"allround"},{year:"2013",make:"Dodge",model:"SRT Viper GTS",tag:"Loyalty (FH1)",note:"Returning reward for playing Forza Horizon 1 [WIKI].",disc:"allround"},{year:"2024",make:"Chevrolet",model:"Corvette E-Ray",tag:"Loyalty (Motorsport)",note:"Returning reward for Forza Motorsport (2023) [WIKI].",disc:"top"}]},{title:"Starter Cars (community-sourced)",note:"Handed to you at the start of the festival per community guides. Not enumerated by Wikipedia.",items:[{year:"1989",make:"Nissan",model:"Silvia K'S",tag:"Drift-friendly",note:"Great for learning Touge and drift zones.",disc:"drift"},{year:"1994",make:"Toyota",model:"Celica GT-Four ST205",tag:"All-rounder",note:"Balanced for mixed road and light off-road.",disc:"allround"},{year:"1970",make:"GMC",model:"Jimmy",tag:"Off-road",note:"Heavy on tarmac, strong in the northern mountains.",disc:"offroad"}]},{title:"Prologue & Festival Cars (community-sourced)",note:"Appear during the opening drive and early festival events per community guides.",items:[{year:"2024",make:"Nissan",model:"GT-R Nismo",tag:"Prologue",note:"Driven through the Hokubu fields at the very start.",disc:"top"},{year:"2021",make:"RJ Anderson",model:"#37 Polaris RZR Pro 4 Truck",tag:"Prologue",note:"Snow-circuit opener.",disc:"offroad"},{year:"1995",make:"Porsche",model:"911 GT2",tag:"Prologue",disc:"top"},{year:"",make:"Mazda",model:"RX-7 Type R",tag:"Prologue",disc:"drift"},{year:"2023",make:"BMW",model:"M2",tag:"Prologue",disc:"allround"},{year:"2020",make:"Toyota",model:"GR Supra",tag:"Prologue",disc:"allround"}]},{title:"Event Path Reward Cars (community-sourced)",note:"Cars tied to specific Horizon Festival and Explore Japan milestones (from the IGN walkthrough).",items:[{year:"2022",make:"Toyota",model:"GR86",disc:"allround"},{year:"2001",make:"Mitsubishi",model:"Lancer Evolution VI GSR TM Edition",disc:"offroad"},{year:"2024",make:"Ram",model:"1500 TRX",disc:"drag"},{year:"",make:"Aston Martin",model:"Vulcan",tag:"Loyalty reward",note:"Forza Loyalty reward if you played earlier titles.",disc:"top"},{year:"",make:"Ford",model:"RS200",tag:"Wristband event",note:"Pier Pressure — Tokyo docks.",disc:"offroad"},{year:"",make:"Lotus",model:"Exige WTAC",tag:"Road Racing",disc:"allround"},{year:"",make:"Subaru",model:"Impreza",tag:"Sekibe Scramble",disc:"offroad"},{year:"",make:"Mitsubishi",model:"Lancer Evo",tag:"Sekibe Scramble",disc:"offroad"},{year:"",make:"Lamborghini",model:"Huracán Sterrato",tag:"Dirt Racing max",disc:"offroad"},{year:"",make:"Mini",model:"JCW Buggy",tag:"Cross Country",disc:"offroad"},{year:"",make:"GMA",model:"T.50",tag:"Speed Traps",disc:"top"},{year:"",make:"Porsche",model:"911 GT3 RS '12",tag:"Speed Zones",disc:"top"},{year:"",make:"M12S",model:"Warthog CST",tag:"Danger Signs",disc:"drag"},{year:"",make:"Mazda",model:"RX-8 #99",tag:"Drift Zones",disc:"drift"},{year:"",make:"Mercedes-Benz",model:"G 65",tag:"Trailblazers",disc:"offroad"},{year:"",make:"Lexus",model:"LFA FE",tag:"Street / Touge ultimate",disc:"allround"},{year:"",make:"Honda",model:"NSX-R '05",tag:"Regional Mascots",disc:"allround"},{year:"",make:"Audi",model:"R8 '13",tag:"Day Trips",disc:"allround"},{year:"",make:"Nissan",model:"240 #777",tag:"Drift Club Japan",disc:"drift"},{year:"",make:"Honda",model:"Civic '84",tag:"Moto Auto Zine",disc:"allround"},{year:"",make:"Toyota",model:'GR86 "86 Stories"',tag:"Yuji's Auto",disc:"allround"},{year:"",make:"Porsche",model:"918",tag:"Horizon Play",disc:"top"},{year:"",make:"Porsche",model:"Cayman GT4 RS",tag:"Road Rivals",disc:"allround"},{year:"",make:"Opel",model:"Manta 400",tag:"Dirt Rivals",disc:"offroad"},{year:"",make:"",model:"#37 Pro 2 Truck",tag:"Cross Country Rivals",disc:"offroad"},{year:"",make:"Subaru",model:"Vivio FE",tag:"Horizon Life",disc:"allround"},{year:"",make:"Nissan",model:"Nismo GT-R '24",tag:"Touge & Street Rivals",disc:"allround"},{year:"",make:"Koenigsegg",model:"Agera RS",tag:"Explore Japan landmark",disc:"top"}]},{title:"Featured Roster (community-sourced sample)",note:"A slice of the launch roster — the full list spans 64+ pages on IGN.",items:[{year:"1969",make:"Toyota",model:"2000GT",disc:"allround"},{year:"1964",make:"Ferrari",model:"250 GTO",disc:"allround"},{year:"1954",make:"Mercedes-Benz",model:"300SL",disc:"allround"},{year:"1994",make:"Ferrari",model:"355 Berlinetta",disc:"allround"},{year:"1991",make:"Ferrari",model:"512 TR",disc:"allround"},{year:"1973",make:"Porsche",model:"911 Carrera RS",disc:"allround"},{year:"1995",make:"Porsche",model:"911 GT2",disc:"top"},{year:"2004",make:"Porsche",model:"996 GT3",disc:"top"},{year:"1982",make:"Porsche",model:"911 Turbo",disc:"allround"},{year:"1989",make:"Porsche",model:"944 Turbo",disc:"allround"}]}]},bestCars:{intro:"Forget hunting for one 'best' car — Horizon is built so different machines win at different things. These are the standout picks for each discipline, pulled from the walkthrough reward cars and what reviewers actually rated.",categories:[{cat:"Top Speed / Fastest",picks:[{car:"GMA T.50",why:"Reward for Speed Traps — a raw, lightweight hypercar."},{car:"Koenigsegg Agera RS",why:"Granted for discovering Japanese landmarks via Explore Japan."},{car:"2025 GR GT Prototype",why:"The cover car; built for straight-line pace."},{car:"Nissan Nismo GT-R '24",why:"Top reward from Touge & Street Rivals."}]},{cat:"Drifting",picks:[{car:"Nissan 240 #777",why:"Drift Club Japan reward — purpose-built slide machine."},{car:"Mazda RX-8 #99",why:"Drift Zones reward; rotary balance."},{car:"Nissan Silvia K'S (starter)",why:"Rocket-Bunny-style starter that rewards precise throttle."},{car:"Mazda RX-7 Type R",why:"Featured in the prologue Touge intro."}]},{cat:"Drag Racing",picks:[{car:"M12S Warthog CST",why:"Danger Signs reward; brutal launch."},{car:"Ram 1500 TRX",why:"First-wristband reward with serious grunt."},{car:"RJ Anderson #37 Polaris RZR Pro 4",why:"Prologue truck; strong off-the-line."}]},{cat:"Off-road / Rally",picks:[{car:"Lamborghini Huracán Sterrato",why:"Dirt Racing max reward."},{car:"Mini JCW Buggy",why:"Cross Country reward."},{car:"#37 Pro 2 Truck",why:"Cross Country Rivals reward."},{car:"GMC Jimmy (starter)",why:"Surprisingly capable in the snowy north."}]},{cat:"Best All-rounder Starter",picks:[{car:"Toyota Celica GT-Four ST205",why:"Balanced AWD turbo — comfortable on road and light trails while you learn."}]}],faq:[{q:"Is there one single best car in Forza Horizon 6?",a:"No. The right car depends on the job — top speed, drift, drag, off-road and all-round driving each favour different builds. Use the picks above as a starting point and tune to taste."},{q:"What is the best all-rounder starter car?",a:"The Toyota Celica GT-Four ST205: a balanced AWD turbo that is comfortable on road and light trails while you learn the map. The Nissan Silvia K'S is the better pick if you want to learn drifting, and the GMC Jimmy if you'll spend time off-road or in the snow."},{q:"What is the fastest car, and how do I unlock it?",a:"The GMA T.50 is the top-speed pick and is granted for clearing Speed Traps. The Koenigsegg Agera RS comes from discovering Japanese landmarks via Explore Japan, and the 2025 GR GT Prototype (the cover car) is built for straight-line pace."},{q:"What is the best car for drifting?",a:"The Nissan 240 #777 (Drift Club Japan reward) and the Mazda RX-8 #99 (Drift Zones reward) are purpose-built slide machines; the Nissan Silvia K'S starter also rewards precise throttle control."},{q:"What is the best car for drag racing?",a:"The M12S Warthog CST (Danger Signs reward) has a brutal launch, the Ram 1500 TRX is a first-wristband reward with serious grunt, and the RJ Anderson #37 Polaris RZR Pro 4 is strong off the line."},{q:"What is the best off-road / rally car?",a:"The Lamborghini Huracán Sterrato (Dirt Racing max reward) and the Mini JCW Buggy (Cross Country reward) handle loose surfaces best; the #37 Pro 2 Truck and GMC Jimmy are solid too."},{q:"How many cars are in Forza Horizon 6 at launch?",a:"550+ cars at launch [WIKI]. The lists above are curated, sourced picks — not the full roster."},{q:"What is the best car for farming credits?",a:"Any of the fast event-reward cars above will do; pair it with higher difficulty and assists off for up to +125% credit payouts, and three-star PR stunts for Super Wheelspins."}]},regions:{intro:"Forza Horizon 6 is set in a fictionalised Japan with the largest open-world map in the series [WIKI]. The areas below are named in Wikipedia; community guides report the full map spans 10 regions — we list what is encyclopaedically confirmed and clearly mark the rest.",items:[{name:"Tokyo",known:!0,pin:{x:70,y:58},blurb:"The largest urban area in any Forza Horizon game — about five times the size of previous city areas [WIKI]. Districts include Shibuya Crossing, Ginko Avenue, and Tokyo Tower, linked by elevated highways. Mix of neon downtown, suburbs, and industrial docks [WIKI].",features:["Shibuya Crossing","Ginko Avenue","Tokyo Tower","Elevated highways","Neon downtown · suburbs · industrial docks","≈5× the size of prior city areas [WIKI]"]},{name:"Legend Island",known:!0,pin:{x:88.2,y:26.8},blurb:"A special area unlocked with the Gold Wristband, featuring unique challenges, exclusive events, and a second Horizon Festival [WIKI].",features:["Gold Wristband unlock","Unique challenges","Exclusive events","Second Horizon Festival"]},{name:"Rural Japan",known:!0,pin:{x:30,y:71},blurb:"The countryside, home to the Estate — your customisable mountainside property [WIKI]. Scenic driving and overlooks.",features:["The Estate (customisable property)","Mountainous scenery","Open-world building"]},{name:"Mount Fuji",known:!0,pin:{x:43.2,y:40.3},blurb:"Japan's iconic peak appears as a backdrop behind Tokyo and the key art — a landmark rather than a drivable district [WIKI].",features:["Backdrop landmark","Visible from Tokyo","Key-art centerpiece"]},{name:"Hokkaido",known:!1,pin:{x:45,y:9},blurb:"Community-reported northern region — snow-covered tundra and ice-road driving. Named by community guides; not officially confirmed by Wikipedia.",features:["Community: snow & ice driving","Northernmost area","Contributes to Discover Japan stamps"]},{name:"Tohoku",known:!1,pin:{x:64,y:19},blurb:"Community-reported northeast region of mountain passes and coastal roads. Not officially named by Wikipedia.",features:["Community: mountain passes","Coastal drives","Discover Japan stamps"]},{name:"Chubu",known:!1,pin:{x:50,y:48},blurb:"Community-reported central-Honshu region — the Japan Alps and long tunnel networks. Not officially named by Wikipedia.",features:["Community: Japan Alps","Tunnel networks","Discover Japan stamps"]},{name:"Kansai (Osaka)",known:!1,pin:{x:60,y:66},blurb:"Community-reported region around the old capital — dense city grid and highway networks. Not officially named by Wikipedia.",features:["Community: urban grid","Highway network","Discover Japan stamps"]},{name:"Kyushu",known:!1,pin:{x:17,y:85},blurb:"Community-reported southwest region of volcanic terrain and winding coastal roads. Not officially named by Wikipedia.",features:["Community: volcanic terrain","Coastal winding roads","Discover Japan stamps"]},{name:"Okinawa",known:!1,pin:{x:11,y:95},blurb:"Community-reported southern island chain — flat island roads and beachfront straights. Not officially named by Wikipedia.",features:["Community: island roads","Beachfront straights","Discover Japan stamps"]}],legend:[{icon:"PR",label:"Speed Traps, Speed Zones, Danger Signs, Drift Zones, Trailblazers"},{icon:"M",label:"Mascots — drive through them for credits"},{icon:"PH",label:"Photo & landmark spots (Collection Journal stamps)"},{icon:"H",label:"The Estate — your customisable property"},{icon:"G",label:"Garages — 8 car-display + fast-travel points"},{icon:"A",label:"Aftermarket Cars — green CT icons on the map"},{icon:"T",label:"Treasure Cars — photo-clue only, no marker until found"}],prStunts:[{t:"Speed Traps",d:"Flash through a gate above a target speed. Three-star for Super Wheelspins and Skill Points."},{t:"Speed Zones",d:"Hold a target average speed across a measured stretch of road."},{t:"Danger Signs",d:"Launch off a ramp and fly as far as the jump will carry you."},{t:"Drift Zones",d:"Bank the highest drift score before you cross the finish line."},{t:"Trailblazers",d:"Point-to-point sprint against the clock — the shortest, smoothest line wins."}],tips:["Fast-travel to any road you've already driven — explore first, blink later.","Discover Japan stamps unlock Barn Find rumors and feed the Collection Journal.","Photo spots (PH) double as Collection Journal stamps — stop and shoot them as you pass.","Garages (G) are free fast-travel points; unlock all 8 early to cross the huge map in seconds."]},beginner:{intro:"New to Horizon Japan? Follow this path — distilled from the Reddit no-spoiler guide, RedBull tips, Polygon's 10 tips, and the official First Drive, cross-checked against Wikipedia's confirmed systems.",steps:[{n:1,title:"Qualify, then Invitational",body:"Run the Horizon Qualifiers, then the Horizon Invitational. Finishing it grants your first (Yellow) Wristband and unlocks the festival, multiplayer, and free cars."},{n:2,title:"Pick a starter that matches your style",body:"Silvia K'S for drift, Celica GT-Four for balance, GMC Jimmy for off-road. All three end up in your garage anyway."},{n:3,title:"Don't blow credits at the Autoshow",must:!0,body:"Wheelspins, story events, and the Festival Playlist hand out cars fast. Spend early credits tuning your starter instead."},{n:4,title:"Earn Discover Japan stamps",must:!0,body:"Explore regions, discover landmarks, and photograph them. Stamps feed your Collection Journal and unlock content [WIKI]."},{n:5,title:"Farm mascots",body:"Mascots sit across the map — drive through them for credits. (Exact count is community-reported; clear them as you explore.)"},{n:6,title:"Grab Aftermarket Cars",body:"Watch the minimap for green CT car icons. They're secondhand, fully tuned, and cheaper than the Autoshow."},{n:7,title:"Use ANNA when you're tired",body:"The AI assistant can drive you to a destination; Cinema Mode hides the UI for screenshot tours."},{n:8,title:"Nail Drag Meets",body:"Handbrake + launch control, release on the final light. Jumping the gun lurches you forward."},{n:9,title:"Three-star PR stunts",body:"Speed Zones, Danger Signs, and Drift Zones earn Super Wheelspins and Skill Points for Car Mastery trees."},{n:10,title:"Turn up difficulty for credits",body:"Higher difficulty + assists off can pay up to +125% credits per race. Only when you can still win."},{n:11,title:"Photo everything",body:"Press Up for photo mode. The Horizon Promo challenge gives festival points per car photographed, and the journal wants landmark shots."},{n:12,title:"Fast-travel smart",must:!0,body:"You can teleport to almost anywhere you've already visited — including the middle of a road. Explore first, blink later."},{n:13,title:"Unlock the Estate",body:"The Estate is your customisable mountainside property in rural Japan [WIKI] — build and decorate it, and collect daily credit payouts via the My Horizon message center.",must:!0},{n:14,title:"Treasure & Barn loop",body:"9 Treasure Cars hide behind photo clues (no marker until found, no progression needed, no restoration wait). 15 Barn Finds appear as rumours once your Discover Japan stamps unlock them, then need real-time restoration. Both rosters are fully listed on the Cars page."}],settings:["Enable Proximity Radar (HUD & Gameplay) to see cars behind you.","Raise camera FOV (Video) for a wider view.","Build your own music playlist — the 9 in-game stations repeat fast.","Turn off car damage if you'd rather keep cars pristine."],glossary:[{t:"Wristbands",d:"The progression ladder. Race, stunt, and explore to climb from Yellow up to Gold — which opens Legend Island."},{t:"Festival Playlist",d:"A new season every week across a four-week series, each with exclusive cars and credit payouts."},{t:"ANNA",d:"Your in-game co-driver. She can drive you to a destination, or you can flip on Cinema Mode to hide the HUD for clean photo runs."},{t:"Wheelspin / Super Wheelspin",d:"Free prizes from level-ups and PR stunts — cars, credits, and cosmetics."},{t:"PR Stunt",d:"Speed Traps, Speed Zones, Danger Signs, Drift Zones, and Trailblazers. Three-star them for Super Wheelspins."},{t:"Discover Japan",d:"The exploration meta — earn stamps by finding landmarks, photographing them, and driving the map."},{t:"Collection Journal",d:"Logs every photo spot and landmark you find as you roam Japan."},{t:"Aftermarket Car",d:"Secondhand, fully-tuned cars marked by green CT icons on the map — cheaper than the Autoshow."},{t:"Treasure / Barn Car",d:"Free hidden cars: Treasure via photo clues, Barn Finds via stamp-gated rumors."},{t:"The Estate",d:"Your customisable mountainside property in rural Japan, with daily credit payouts."},{t:"EventLab",d:"Build your own events and tracks, then publish them for the festival to play."},{t:"Horizon Play",d:"Multiplayer mash-ups: Spec Racing, The Eliminator (72 players), Touge Showdown, Hide & Seek."}],credits:["Crank difficulty up and switch assists off — up to +125% credits per race, if you can still win.","Three-star PR stunts for Super Wheelspins; chain them with Skill Chains to feed Car Mastery trees.","Drive through Mascots scattered across the map for easy credits as you explore.","Claim The Estate's daily credit payouts via My Horizon → Message Center.","Work the weekly Festival Playlist — its reward cars and payouts compound fast."],pitfalls:[{t:"Don't blow credits at the Autoshow",b:"Wheelspins, story events and the Festival Playlist hand out cars fast — spend early credits tuning your starter instead of buying the headline car."},{t:"Don't ignore Discover Japan stamps",b:"Stamps unlock Barn Find rumours and feed your Collection Journal. Skipping exploration means missing free classic cars."},{t:"Don't leave assists on while chasing +125% credits",b:"Higher difficulty only pays the bonus with assists OFF. Keep the aids on and you stay at the base payout."},{t:"Don't miss the green CT aftermarket icons",b:"Aftermarket Cars are secondhand, fully tuned and cheaper than the Autoshow — the best early-game value on the map."},{t:"Don't mix up the two sets of '8'",b:"Wikipedia confirms The Estate plus 8 Garages (fast-travel points). The 8 buyable houses are a separate, community-sourced list — both exist, they are just not the same 8."},{t:"Don't fast-travel to places you haven't driven",b:"You can only blink to roads you've already visited. Explore first, then teleport."},{t:"Don't brute-force PR stunt 3-stars",b:"Pick a car built for the discipline and tune it; three-starring with the wrong machine wastes hours."},{t:"Don't scrap your starter cars",b:"Silvia (drift), Celica (all-rounder) and Jimmy (off-road) each earn their keep as tool cars — keep them."},{t:"Don't skip The Estate's daily payout",b:"Claim it via My Horizon → Message Center; it's a steady credit trickle while you explore."},{t:"Don't only grind one event type",b:"Sweep Mascots and Photo Spots (PH) as you drive — they stack Collection Journal stamps and unlock content faster."}]},barnFinds:{count:15,countSource:"IGN, Windows Central, PC Gamer, Red Bull",status:"mapped",intro:"Barn Finds are classic cars abandoned in barns across Japan, gated behind your Discover Japan stamps. There are 15 of them, unlocked in batches of one to four as you climb the seven Discover Japan stamp tiers from Visitor to Master Explorer. Wikipedia does not enumerate this mechanic, so the roster below is guide-sourced and cross-checked between IGN, Windows Central, PC Gamer and Red Bull.",howTo:["Earn Discover Japan stamps — mascots smashed, food delivery jobs, street and touge races, and above all the yellow-badge story missions.","Each stamp tier unlocks new Barn Find rumours (generally one to four at a time).","A purple circle appears on the map — drive into it to reveal the barn's rough area.","Search the circle for the barn; you can spot it fast by flying a Drone over the zone.","The car is sent for restoration, which takes real time — a couple of hours up to several days. You can pay credits to skip it, but it is rarely worth it."],list:[{n:1,car:"2005 Honda NSX-R GT",stamp:"Visitor (yellow, 1/7)",region:"Ohtani",hint:"In the woods along the north-west edge of the search area, where the two nearby roads pincer together. Rough terrain — don't bring a slow city car."},{n:2,car:"1969 Toyota 2000GT",stamp:"Sightseer (green, 2/7)",region:"Ito",hint:"North Ito, not far from Minka House. Small patch of trees near the seawall on the south-eastern edge of the search zone, between the two paths down to the beach."},{n:3,car:"1987 Ford Sierra Cosworth RS500",stamp:"Sightseer (green, 2/7)",region:"Ito",hint:"Southern Ito, up the small wooded hill just south of the crossroads junction on the southern edge of the search zone. You can almost see it from the road."},{n:4,car:"1971 Nissan Skyline 2000GT-R",stamp:"Traveller (blue, 3/7)",region:"Nangan",hint:"Far south of the search area, past the houses on the main road — a dirt path leads off towards the barn."},{n:5,car:"1989 Nissan Pao",stamp:"Traveller (blue, 3/7)",region:"Minamino",hint:"Woods on the north-east edge of the search area, down a dirt path leading off the main road. The Dodge Charger R/T Treasure Car is a short drive east."},{n:6,car:"1982 Porsche 911 Turbo 3.3",stamp:"Pathfinder (pink, 4/7)",region:"Ohtani / Tokyo City",hint:"Bamboo forest beside the dirt road between the two main roads that lead to Mei's House, in the Ohtani side of the search zone."},{n:7,car:"1984 Peugeot 205 Turbo 16",stamp:"Pathfinder (pink, 4/7)",region:"Shimanoyama",hint:"Barn at the end of the wide dirt road that climbs a short hill from the main road, in the north-east of the search zone. Visible from the main road."},{n:8,car:"1962 Lincoln Continental",stamp:"Pathfinder (pink, 4/7)",region:"Hokubu",hint:"Patch of trees beside the colourful flower fields just south of the centre of the search zone, near Shikisai-No-Oka."},{n:9,car:"1998 Nissan #23 Pennzoil NISMO Skyline GT-R",stamp:"Pathfinder (pink, 4/7)",region:"Takashiro",hint:"Woods on the eastern edge of the search area, inside the 'u' bend of the road. The Lancer Evolution III GSR Treasure Car is by the waterfall nearby."},{n:10,car:"1997 Mitsubishi Montero Evolution",stamp:"Navigator (orange, 5/7)",region:"Shimanoyama",hint:"Forest on the south-west edge of the search area; a dirt path leads in from the main road not far from the Bandai Azuma Skyline Drift Zone."},{n:11,car:"1997 Lamborghini Diablo SV",stamp:"Navigator (orange, 5/7)",region:"Ito",hint:"Eastern edge of the search zone — down the hill with the felled trees opposite the blue digger, then around the bend on your right."},{n:12,car:"1998 Nissan R390 (GT1)",stamp:"Adventurer (purple, 6/7)",region:"Ohtani",hint:"Dirt path along the north-eastern edge of the search area, near the Ohtani / Shimanoyama border. Also reachable from the Bridge Underpasses Trailblazer start gate."},{n:13,car:"2005 Mitsubishi #1 Sierra Sierra Enterprises Lancer Evolution Time Attack",stamp:"Adventurer (purple, 6/7)",region:"Shimanoyama",hint:"Woods almost dead centre of the search area, overlooking Narai-Juku to the south. Take the high dirt road up from the Narai-Juku Circuit road race, then the path on your right."},{n:14,car:"1983 Nissan #11 Tomica Skyline Turbo Super Silhouette",stamp:"Master Explorer (gold, 7/7)",region:"Ito",hint:"South-western edge of the search area. Where the main road enters the zone from the west, a wide dirt path runs south between some oddly skinny trees — easy to pick out on the map."},{n:15,car:"1991 Mazda #55 Mazda 787B",stamp:"Master Explorer (gold, 7/7)",region:"Takashiro",hint:"Woods directly north of the search area, past the buildings, walking trails and farmland. Dirt path off the main road at the north-west edge of the zone."}],note:"We deliberately give descriptive landmark pointers, not map coordinates — the four guides we cross-checked describe these spots in words, and inventing coordinate pairs would be exactly the kind of fabrication this site avoids. We track all 15 Barn Finds; some interactive maps still list only 14 (a stale count, corrected against IGN's May 2026 update). Restoration takes real time (hours to days), so start hunting early."},treasureCars:{count:9,countSource:"GamesRadar, PC Gamer, Gamereactor, GamingBolt",status:"mapped",intro:"Treasure Cars are abandoned vehicles hidden across Japan, found only via photo clues (no map marker until you are nearly on top of one). There are nine — one per region of the mainland, with the ninth in Tokyo City. Unlike Barn Finds they need no stamp progression and no restoration: just drive up and claim them, in any order. Wikipedia does not enumerate this mechanic, so the roster below is guide-sourced and cross-checked across four outlets.",howTo:["Drive around Japan; Mei hands you a photo clue when you pass near a Treasure Car.","The photo is the puzzle — study the background (mountains, signs, road shape) to narrow it down.","Find the exact spot, claim the car, and it's in your collection for free — no restoration wait.","Once discovered, the location stays marked on your map.","A systematic north-to-south sweep covers all nine in a couple of hours."],list:[{n:1,car:"1991 Nissan Figaro",region:"Tokyo City",grid:"D 234",clue:"Forgotten in one of the city's car parks near the iconic Rainbow Bridge.",hint:"Small car park on the Tokyo Bay waterfront — north-east of the Rainbow Bridge, north-west of the Daikoku Parking Area marker."},{n:2,car:"1969 Dodge Charger R/T",region:"Minamino",grid:"C 417",clue:"Spotted out the back of the Minamino region's golf course clubhouse.",hint:"Behind the clubhouse and convenience store buildings on the east side of the golf course, near the line of golf carts. The course sits centrally, close to the Airfield Trail dirt race."},{n:3,car:"1985 Mazda RX-7 GSL-SE",region:"Ohtani",grid:"D 357",clue:"Spotted near some radio towers in the Ohtani region.",hint:"By the radio towers on the western border where Ohtani meets Shimanoyama — not the towers further north."},{n:4,car:"1987 Porsche 959",region:"Shimanoyama",grid:"A 661",clue:"Spotted outside a corner shop in the Shimanoyama region.",hint:"Just outside the convenience store on the south-eastern side of Narai-Juku, the small town in the north of the region."},{n:5,car:"1981 BMW M1",region:"Hokubu",grid:"B 510",clue:"Left under one of the railway bridges in the Hokubu region.",hint:"Under the railway bridge surrounded by crop fields in the north of the region, roughly north-east of the Shikisai-No-Oka flower fields. Look for the support column covered in scaffolding."},{n:6,car:"1995 Mitsubishi Lancer Evolution III GSR",region:"Takashiro",grid:"B 517",clue:"Abandoned below a waterfall, near one of the temples.",hint:"On the dirt road in front of Nachi Falls in the north-western corner of the region. The waterfall also hides a 5,000 XP Bonus Board."},{n:7,car:"1974 Lancia Stratos HF Stradale",region:"Sotoyama",grid:"C 483",clue:"Abandoned near the Tateyama Kurobe Alpine Route.",hint:"Beside a lone building on the mountain along the east–west main road that forms the Tateyama Kurobe Alpine Route. Head for the base of the tallest ski path."},{n:8,car:"2005 Ford GT",region:"Nangan",grid:"A 676",clue:"Spotted down one of the Nangan region's coastal trails.",hint:"Beach car park at the end of an unmarked dirt track at the easternmost point of the region, off the coastal road that looks back towards Tokyo City."},{n:9,car:"1985 Nissan Safari Turbo",region:"Ito",grid:"D 123",clue:"Left to weather the elements near the Wind Farm.",hint:"At the base of one of the wind turbines along the Turbine Trail Drift Zone in the north of the region."}],note:"All nine are free. GamingBolt reports that claiming every Treasure Car unlocks the 'Lost and Found' badge — treat that one as single-sourced. We show GamingBolt's map-grid label (letter+number, e.g. D 234) for each car as a navigation aid — that is their overlay grid, not an in-game GPS readout, and we still publish landmark descriptions rather than invented coordinates. Barn Finds remain landmark-only, since no trusted numeric source exists for them."},aftermarket:{count:null,status:"pending",intro:"Aftermarket Cars are secondhand vehicles scattered across the map. They match your current campaign progression, come fully tuned with kits, and cost less than the Autoshow. (Wikipedia confirms deep car customisation but does not define this specific system; details below are community-sourced.)",howTo:["Watch the minimap for green CT car icons while driving to events.","Drive up and buy directly — no auction house needed.","They're a cheap, ready-to-race alternative to the Autoshow early on."],note:"Aftermarket Cars are one of three ways to get cars fast (alongside Wheelspins and Treasure Cars)."},forzaEdition:{intro:"Forza Edition (FE) cars are rare, specially-tuned variants found on the road and as rewards. Wikipedia does not confirm this category; the examples below are community-sourced.",examples:[{car:"Lexus LFA FE",note:"Ultimate reward for Street Racing & Touge."},{car:"Subaru Vivio FE",note:"Horizon Life Events reward."},{car:"Nissan Nismo GT-R '24",note:"Top reward from Touge & Street Rivals."}],note:"More Forza Edition cars exist and turn up as you explore — collect them as you find them."},houses:{count:8,countLabel:"player houses (community-sourced)",intro:'Two different sets of "8" in Horizon Japan — and mixing them up is the single most common error in FH6 property guides. Wikipedia confirms one headline property, The Estate, plus 8 Garages that double as fast-travel and car-display points [WIKI]. Separately, community guides enumerate 8 buyable player houses, each with a permanent perk that stays active wherever you spawn; Wikipedia does not enumerate those, so they are labelled community-sourced [RPS, TECH, FH6GUIDE]. The Estate (Yashiki House) is the headline — a fully buildable plot you shape with an upgraded EventLab toolset. Houses unlock through the seven Discover Japan stamp tiers (yellow Visitor → green Sightseer → blue Traveller → pink Pathfinder → orange Navigator → purple Adventurer → gold Master Explorer).',items:[{name:"Mei's House",region:"Ohtani",price:"Free",unlock:"Yellow Stamp (tutorial)",perk:"Wheeler Dealer",perkDetail:"Unlocks car trading at the Autoshow",note:"Auto-unlocks after the tutorial. Grab it first — it opens Autoshow car trading.",featured:!1},{name:"The Estate (Yashiki House)",region:"Hokubu",price:"10,000 Cr",unlock:"1st Discover Japan Stamp",perk:"Estate Builder",perkDetail:"Build & customise tracks, structures, water and foliage",note:"The buildable base. Clear the 19 objects blocking the land, pay 10,000 Cr, and you get a permanent, friends-visitable plot. Up to 12 players can co-create via Horizon Collab.",featured:!0},{name:"Tokyo House",region:"Tokyo City",price:"3,000,000 Cr (free with VIP)",unlock:"Yellow Stamp",perk:"Daily Wheelspin",perkDetail:"One free spin every day",note:"Best long-term credit investment. VIP players get it for free.",featured:!1},{name:"Minka House",region:"Ito",price:"450,000 Cr",unlock:"Green Stamp",perk:"Credit Stunts",perkDetail:"+10% credits from Stunt Party",note:"Solid mid-game earner from skill-chain stunts.",featured:!1},{name:"Hakusan Mountain Lodge",region:"Sotoyama",price:"635,000 Cr",unlock:"Blue Stamp",perk:"+1 Garage Slot & +10% Horizon Life credits",perkDetail:"Extra display slot + bonus life credits",note:"Best ROI — the extra garage slot is a genuine bonus.",featured:!1},{name:"Fuji Unkai House",region:"Shimanoyama",price:"830,000 Cr",unlock:"Orange Stamp",perk:"Career Driver",perkDetail:"+10% credits from Jobs",note:"Best for players who grind Jobs and careers.",featured:!1},{name:"Soko 78",region:"Tokyo City",price:"980,000 Cr",unlock:"Purple Stamp",perk:"Import/Export",perkDetail:"-5% Autoshow discount",note:"Pays for itself after a few high-end car purchases.",featured:!1},{name:"Vision House",region:"Ohtani",price:"1,500,000 Cr",unlock:"Gold Stamp (Master Explorer)",perk:"+1 Garage Slot & +10% LINK Skill score",perkDetail:"Extra slot + convoy skill bonus",note:"Endgame property for convoy players; needs serious time to unlock.",featured:!1}],estateBuild:[{t:"Main House",d:"Customisable interior and living spaces"},{t:"Garage Wing",d:"Vehicle display, up to 50 slots"},{t:"Workshop",d:"Tuning bay and visual customisation"},{t:"Viewing Deck",d:"Panoramic photo spot for photo mode"},{t:"Driveway & Paths",d:"Connect buildings and shape layouts"},{t:"Gardens & Landscaping",d:"Trees, bushes, flowers, ponds"},{t:"Decorative Items",d:"Benches, signs, lights, barriers"},{t:"Seasonal Changes",d:"Your Estate transforms with Japan's dynamic seasons"}],garages:{intro:"Horizon Japan has 8 Garages — a different set of 8 from the buyable houses above. These double as free fast-travel points and shareable car-display spaces with customisable, community-downloadable interiors [WIKI]. The Estate is the only property Wikipedia confirms; the 8 Garages are the other Wikipedia-confirmed piece of the property picture.",note:"Don't confuse these with houses — they're fast-travel/car-display points, not owned properties.",list:[{slot:1,status:"unconfirmed"},{slot:2,status:"unconfirmed"},{slot:3,status:"unconfirmed"},{slot:4,status:"unconfirmed"},{slot:5,status:"unconfirmed"},{slot:6,status:"unconfirmed"},{slot:7,status:"unconfirmed"},{slot:8,status:"unconfirmed"}]},order:[{n:1,name:"Mei's House",why:"Free, auto-unlocks after the tutorial; opens Autoshow trading."},{n:2,name:"The Estate",why:"Only 10,000 Cr; your permanent, buildable base."},{n:3,name:"Hakusan Mountain Lodge",why:"Best ROI — extra garage slot and +10% life credits."},{n:4,name:"Minka House",why:"Cheap +10% Stunt Party credits."},{n:5,name:"Tokyo House",why:"Daily Wheelspin — the strongest long-term grind (free with VIP)."},{n:6,name:"Fuji Unkai House",why:"+10% Job credits for career-focused players."},{n:7,name:"Soko 78",why:"-5% Autoshow discount pays off on big buys."},{n:8,name:"Vision House",why:"Endgame; needs the Gold Master Explorer Stamp."}],tips:["Unlock Mei's House first — it's free and opens car trading at the Autoshow.","The Estate costs just 10,000 Cr and is your permanent, buildable base; claim it early.","House perks stay active wherever you spawn, so owning all 8 stacks every bonus.","Most houses need a Discover Japan Stamp tier (yellow Visitor → gold Master Explorer) before they're buyable, and the same seven tiers gate the 15 Barn Finds.","Hakusan Mountain Lodge gives the best ROI: an extra garage slot plus +10% Horizon Life credits.","Tokyo House's daily Wheelspin is the strongest long-term credit grind (free with VIP).","Garages are separate fast-travel points — unlock all 8 to cross the big map in seconds.","At The Estate, up to 12 players co-create via Horizon Collab; browse and download community layouts."]},collectibleRegions:{"Tokyo City":{x:70,y:58},Ohtani:{x:42,y:46},Ito:{x:66,y:54},Nangan:{x:56,y:76},Minamino:{x:47,y:62},Hokubu:{x:45,y:22},Takashiro:{x:31,y:69},Shimanoyama:{x:51,y:41},Sotoyama:{x:46,y:33}},features:[{title:"ANNA",body:"The in-game co-driver. Hand the wheel to her on long drives, or flip on Cinema Mode to hide the HUD for clean photo runs."},{title:"The Estate",body:"Your own patch of rural Japan. Build and decorate it right in the world, then invite friends to cruise through."},{title:"Garages",body:"Eight of them double as fast-travel points, with customisable interiors you can share or download."},{title:"Tuning & paint",body:"Bodykits, rims, liveries — and for the first time in the series, window decals."},{title:"Horizon Play",body:"The returning multiplayer mash-ups: Spec Racing, The Eliminator (72 players at once), Touge Showdown, Hide & Seek."},{title:"Radio",body:"Nine stations, every genre. Or mute them and run your own playlist like a normal person."},{title:"Festival Playlist",body:"A new season drops every week across a four-week series, each with exclusive cars and credit payouts."},{title:"EventLab",body:"Build your own events and tracks, then publish them for the rest of the festival to play."},{title:"Wristbands",body:"The classic progression ladder returns: race, stunt and explore your way up it. Hit Gold and Legend Island opens."},{title:"Collection Journal",body:"Every photo spot and landmark you find gets logged as a stamp as you roam Japan."}],reception:{intro:"Forza Horizon 6 received universal acclaim. On Metacritic it scored 90/100 (PC) and 91/100 (Xbox Series X/S); OpenCritic recorded a 100% recommend rate across 142 reviews [WIKI].",scores:[{outlet:"IGN",score:"10/10"},{outlet:"Eurogamer",score:"5/5"},{outlet:"Giant Bomb",score:"5/5"},{outlet:"Video Games Chronicle",score:"5/5"},{outlet:"Game Informer",score:"9.25/10"},{outlet:"Destructoid",score:"9/10"},{outlet:"PCGamesN",score:"9/10"},{outlet:"Shacknews",score:"9/10"},{outlet:"Pure Xbox",score:"9/10"},{outlet:"Hardcore Gamer",score:"4.5/5"},{outlet:"TechRadar",score:"4.5/5"},{outlet:"GamesRadar+",score:"4/5"},{outlet:"GameSpot",score:"8/10"},{outlet:"PC Gamer (US)",score:"84/100"}],summary:'Critics praised the Japan setting, the expansive open world, the driving feel, and the variety of activities. PC Gamer called the cutscene dialogue "bland" and GamesRadar+ called the story "shallow"; some noted the structure felt conservative [WIKI].',steam:"On Steam the all-platform user score sits at roughly 80% positive. The Simplified Chinese region is the clear outlier — about 67–69% (Mixed / 褒贬不一) across roughly 8,000–10,000 reviews, the lowest of any language — while the other regions average about 86% (Very Positive). The gap is driven by localisation-quality and Xbox-network complaints, not the Japan setting."},development:{intro:"Forza Horizon 6 is developed by Playground Games with assistance from Turn 10 Studios, and published by Xbox Game Studios [WIKI].",timeline:[{date:"Sep 25, 2025",event:"Revealed at Tokyo Game Show [WIKI]."},{date:"Dec 2025",event:"Turn 10 Studios shifts to focus on Forza Horizon 6 [WIKI]."},{date:"Jan 22, 2026",event:"Gameplay premieres at the Xbox Developer Direct [WIKI]."},{date:"Apr 20, 2026",event:"Limited-edition Xbox controller and headset announced (launch May 19) [WIKI]."},{date:"May 7–31, 2026",event:"Crunchyroll subscribers receive a free car voucher [WIKI]."},{date:"May 10, 2026",event:"155 GB preload leaked/decrypted on Steam; Playground banned the leaker [WIKI]."},{date:"May 15, 2026",event:"Premium early access begins [WIKI]."},{date:"May 19, 2026",event:"Worldwide launch on Windows and Xbox Series X/S [WIKI]."},{date:"May 21, 2026",event:"Surpasses 6 million players [WIKI]."},{date:"May 24, 2026",event:"300,000 concurrent players on Steam — 52nd-highest all-time peak [WIKI]."},{date:"Aug 27, 2026",event:'PS5 version reported delayed — Tom Warren (The Verge) says he does not expect it on PS5 in 2026; IGN reports the same from its own sources. Warren stressed it is "definitely still releasing" — delayed, not cancelled. Microsoft and Playground Games have not issued an official statement or a revised date [VERGE, IGN].'},{date:"Late 2026",event:"PlayStation 5 version originally planned — superseded by the delay reports above. Status: delayed, date TBC."}]},media:{intro:"Official trailers from the Forza channel - the best way to see Horizon Japan in motion.",videos:[{id:"oYhaW-Vr4wg",title:"Official Launch Trailer",date:"May 8, 2026",desc:"The full launch trailer - Japan's festivals, mountains, and 550+ cars."},{id:"dj2PkwfrRP0",title:"Gameplay Overview - Xbox Developer Direct 2026",date:"Jan 22, 2026",desc:"First extended gameplay look: the Japan map, new features, and the festival journey."},{id:"HyjVC7fKLVg",title:"The Art of Driving - Official Trailer",date:"Apr 6, 2026",desc:"Larry Chen hosts a tour of the car culture woven through Horizon Japan."},{id:"H1qlPZMfmiU",title:"Official 6-Minute Opening Preview",date:"Xbox",desc:"Six minutes of the opening drive through Japan's roads and landmarks."}]},festivalPlaylist:{intro:"The Festival Playlist is the live content backbone of every Forza Horizon. A new season drops each Thursday across a four-week Series; each season hands out exclusive cars, credits and accolades. Track your own progress below — we never list rewards we can't verify.",note:"Season rewards reset weekly and are only claimable during their own week. Series rewards need a bigger point total across the whole month and are the more desirable cars. Seasons roll over every Thursday at 09:30 ET / 06:30 PT.",freshness:{dataAsOf:"August 31, 2026",nextReset:"September 3, 2026 (Spring season, final week of Series 4)",checkedAgainst:"forza.net Series 4 announcement, Forza Horizon Hub playlist tracker, TechWiser and MMOExp weekly reward roundups",warning:"Reward cars change every Thursday. If today is past the date above, treat this page as out of date and check the official Forza channels before planning your week."},current:{series:4,name:"Horizon Mascot Party",start:"August 13, 2026",end:"September 10, 2026",seasonKey:"winter",seasonLabel:"Winter",seasonStart:"August 27, 2026",seasonEnd:"September 3, 2026",newToHorizon:["1970 Honda N600","1974 Toyota Celica GT","1988 Mitsubishi Starion ESI-R","2018 Exomotive Exocet Sport V8 XP-5"],seasons:[{key:"summer",label:"Summer",dates:"Aug 13 – Aug 20",state:"past",rewards:[{car:"2018 Exomotive Exocet Sport V8 XP-5",pts:20},{car:"1969 Datsun 2000 Roadster",pts:40}]},{key:"autumn",label:"Autumn",dates:"Aug 20 – Aug 27",state:"past",rewards:[{car:"2024 Chevrolet Camaro ZL1",pts:20},{car:"2016 Abarth 695 Biposto",pts:40}]},{key:"winter",label:"Winter",dates:"Aug 27 – Sep 3",state:"current",rewards:[{car:"1974 Toyota Celica GT",pts:20},{car:"1989 Toyota MR2 SC",pts:40}]},{key:"spring",label:"Spring",dates:"Sep 3 – Sep 10",state:"upcoming",rewards:[{car:"1988 Mitsubishi Starion ESI-R",pts:20},{car:"1968 Dodge Dart HEMI Super Stock",pts:40}]}],seriesRewards:[{car:"1970 Honda N600",pts:80},{car:"1967 Renault 8 Gordini",pts:160}],carPassSchedule:[{car:"1987 Porsche #203 Porsche AG 961",date:"Aug 13",state:"past"},{car:"1957 Ford Thunderbird",date:"Aug 20",state:"past"},{car:"1968 Alfa Romeo Tipo 33/2",date:"Aug 27",state:"current"},{car:"1983 Nissan Skyline 2000 Turbo",date:"Sep 3",state:"upcoming"}],nextSeries:{n:5,name:"British Automotive",note:"Announced by Playground Games as the follow-up to Horizon Mascot Party; reward cars not yet published."}},seasons:[{key:"summer",label:"Summer"},{key:"autumn",label:"Autumn"},{key:"winter",label:"Winter"},{key:"spring",label:"Spring"}],events:[{t:"Forzathon Daily",note:"7 small challenges, refresh daily",reward:"Forzathon Points"},{t:"Weekly Forzathon",note:"One themed 4-part chain",reward:"Car + Forzathon Points"},{t:"The Trial",note:"Co-op championship vs. Unbeatable AI",reward:"Exclusive Car"},{t:"Seasonal Playground",note:"PvP playground games",reward:"Exclusive Car"},{t:"Seasonal PR Stunts",note:"Danger Sign, Speed Trap, Speed Zone, Drift Zone & Jumps",reward:"Super Wheelspins"},{t:"Seasonal Championships",note:"2-3 themed races",reward:"Exclusive Cars"},{t:"Treasure Hunt",note:"Solve the clue, find the chest",reward:"Car + 100k Credits"},{t:"Photo Challenge",note:"#Hashtag snapshot at a location",reward:"Car"},{t:"Horizon Arcade",note:"Co-op mini-game series",reward:"Car"},{t:"Monthly Rivals",note:"Time attack vs. the world",reward:"Credits"}]},wiki:{intro:"Quick-reference encyclopedia for Horizon Japan. Systems and terminology that carry across the Forza Horizon series are described in general terms; FH6-specific facts are noted. Nothing here is invented — see the source notes.",cats:[{name:"Core systems",items:[{t:"Drivatars",b:"The AI racers that fill your lobbies. They mimic the driving styles of real Forza players, so they brake, block, and recover more like humans than scripted bots."},{t:"Skill chains",b:"Link drifts, jumps, near-misses and clean racing to build a Skill multiplier. A big chain banks Skill Points (SP) you spend in each car's Mastery tree."},{t:"Influence & Accolades",b:"The festival's progression currency. Earning accolades unlocks wristbands, new events, and the path toward the Horizon Legend rank."},{t:"Wheelspins",b:"Prize spins granted by level-ups, story events and the Festival Playlist. A Super Wheelspin is the rarer version with better odds at cars and credit bundles."},{t:"Forzathon",b:"Rotating in-world events with their own point shop. Show up, complete the themed challenges, and spend Forzathon Points on cars, emotes and cosmetics."},{t:"Festival Playlist",b:"The live content backbone: weekly and daily seasonal challenges. Completing them is the main way to earn exclusive cars and accolades."}]},{name:"Disciplines",items:[{t:"Road Racing",b:"Tarmac circuits and sprints. Favours grip, top speed and braking — the bread-and-butter of the festival."},{t:"Dirt Racing",b:"Loose-surface stages through Japan's countryside. Look for rally-bred hatches and lightweight buggies."},{t:"Cross Country",b:"Rugged point-to-point routes across fields, rivers and trails. Big, tough machinery wins here."},{t:"Street Racing",b:"Illegal-feeling night Touge and city runs. Tight, technical, and all about rhythm and momentum."},{t:"Drag",b:"Straight-line launches from a standing start. Brutal acceleration and launch control decide it."},{t:"Drift",b:"Style over speed — hold the longest, smoothest slide for points. Differentials and tire setup matter most."}]},{name:"Car classes",items:[{t:"Performance Index (PI)",b:"Every car is ranked by a single PI number so you can race fair. Upgrades push the number up; the class is just a band of that number."},{t:"D / C / B / A",b:"The lower four classes. D is the most beginner-friendly; A is fast but still accessible for most events."},{t:"S1 / S2",b:"Superbike-grade and hypercar territory. High power and aero; reserved for the toughest events and PR stunts."},{t:"X (Exceptional)",b:"The unrestricted class for the absolute fastest, most heavily modified machines in the game."}]},{name:"Events & PR stunts",items:[{t:"Circuit & Sprint",b:"Closed-loop and point-to-point races against Drivatars — the core of the campaign."},{t:"Speed Zones",b:"Hit the highest average speed through a marked corridor. Reward Super Wheelspins and accolades."},{t:"Danger Signs",b:"Launch off a ramp and fly as far as possible. A favourite for big-air screenshots."},{t:"Drift & Trailblazer",b:"Score points in a slide, or blaze a ghost route as fast as you can. Both feed Skill Points."}]},{name:"The world",items:[{t:"Horizon Japan",b:"FH6's setting: a fictionalised, festival-take on Japan with the largest open-world map in the series [WIKI]."},{t:"Regions",b:"Japan is split into regions — community guides report around ten, from Tokyo and Mount Fuji to rural towns and islands."},{t:"The Estate",b:"Your customisable mountainside property in rural Japan. Build, decorate, and collect daily credit payouts [WIKI]."},{t:"Garages",b:"Eight garages double as fast-travel points and car-display showrooms across the map [WIKI]."}]},{name:"Glossary",items:[{t:"Wristband",b:"The rank badge you earn by clearing accolade milestones. Higher wristbands unlock more of the map and events."},{t:"Discover Japan stamps",b:"Collectible stamps earned by exploring regions, finding landmarks and photographing them."},{t:"Mascots",b:"Scattered collectibles you drive through for credits as you explore."},{t:"Barn Find / Treasure Car",b:"Two kinds of hidden free cars: barn finds appear as stamp-gated rumours, treasure cars hide behind photo clues with no marker until found."},{t:"ANNA & Cinema Mode",b:"ANNA is the in-car assistant that can drive you to a destination; Cinema Mode hides the UI for clean screenshot tours."}]}]},guides:{intro:"Step-by-step walkthroughs built from the real game systems and the confirmed FH6 details on this site. Where a count comes from community reporting rather than an official source, it's flagged.",items:[{id:"g-first",title:"Your first 10 hours",tag:"Roadmap",shot:"https://i.ytimg.com/vi/oYhaW-Vr4wg/maxresdefault.jpg",lead:"A relaxed path from the Qualifiers to a garage you actually like.",steps:[{n:1,title:"Run the Qualifiers, then the Invitational",body:"Finishing the Horizon Invitational grants your first (Yellow) Wristband and unlocks the festival, multiplayer and free cars."},{n:2,title:"Pick a starter that fits you",body:"Silvia K'S for drift, Celica GT-Four for balance, GMC Jimmy for off-road. All three end up in your garage anyway."},{n:3,title:"Don't spend credits at the Autoshow",body:"Wheelspins, story events and the Festival Playlist hand out cars fast. Tune your starter instead."},{n:4,title:"Photo the landmarks",body:"Press Up for photo mode. Landmark shots feed your Collection Journal and earn Discover Japan stamps."},{n:5,title:"Three-star a few PR stunts",body:"Speed Zones, Danger Signs and Drift Zones pay Super Wheelspins and Skill Points for Car Mastery."},{n:6,title:"Raise difficulty for credits",body:"Higher difficulty with assists off can pay up to +125% credits per race — once you can still win."}]},{id:"g-barn",title:"Unlock all 15 Barn Finds",tag:"Collectibles",shot:"https://i.ytimg.com/vi/dj2PkwfrRP0/maxresdefault.jpg",lead:"Classic cars hidden in barns — gated by exploration, not luck.",steps:[{n:1,title:"Earn Discover Japan stamps",body:"Explore regions, find landmarks and photograph them. Stamps are what unlock barn rumours — the yellow-badge story missions pay out the most."},{n:2,title:"Watch for the rumour notification",body:"Each of the seven stamp tiers unlocks one to four Barn Find rumours. You'll get a purple search circle, not an exact pin."},{n:3,title:"Scout it with the drone",body:"Fly a drone over the purple circle — the moment you spot the barn it gets marked on your map, and you can drive straight to it."},{n:4,title:"Restore and enjoy",body:"Found barns go to your garage. There are 15 across Japan, from the 2005 Honda NSX-R GT to the 1991 Mazda 787B. Restoration takes real time, so start early."}]},{id:"g-treasure",title:"Hunt the 9 Treasure Cars",tag:"Collectibles",shot:"https://i.ytimg.com/vi/H1qlPZMfmiU/maxresdefault.jpg",lead:"Abandoned cars found only through photo clues — no marker until discovered.",steps:[{n:1,title:"Get the photo clue",body:"Treasure clues show a snapshot of the location. Study the background — mountains, signs, road shape — to narrow it down."},{n:2,title:"Match it on the map",body:"There is no map marker. Use landmarks and the horizon to triangulate the spot."},{n:3,title:"Drive over the dig site",body:"Once you're close, the dig prompt appears. There are 9 Treasure Cars, one per mainland region plus Tokyo City — no stamp requirement, no restoration wait."}]},{id:"g-drift",title:"Drift tuning basics",tag:"Tuning",shot:"https://i.ytimg.com/vi/HyjVC7fKLVg/maxresdefault.jpg",lead:"Make almost any car slide predictably.",steps:[{n:1,title:"Tires: lower the pressure",body:"Drop rear tire pressure a few PSI for a looser, more forgiving slide."},{n:2,title:"Differential: bias to the rear",body:"Increase rear deceleration (and acceleration) so the back steps out on throttle lift and braking."},{n:3,title:"Alignment: add caster",body:"More positive caster sharpens turn-in and self-centring, which keeps drifts controllable."},{n:4,title:"Power & weight",body:"RWD with healthy power drifts best; a little ballast at the rear helps rotation. Then practice on the Touge."}]},{id:"g-credits",title:"Farm credits efficiently",tag:"Economy",shot:"https://i.ytimg.com/vi/oYhaW-Vr4wg/maxresdefault.jpg",lead:"Credits fund upgrades and the cars you actually want.",steps:[{n:1,title:"Turn difficulty up",body:"Higher difficulty with assists off can pay up to +125% credits per race — only when you can still win."},{n:2,title:"Three-star PR stunts",body:"Speed Zones, Danger Signs and Drift Zones award Super Wheelspins, which can pay out big credit bundles."},{n:3,title:"Bank Wheelspins",body:"Level-ups, story events and the Festival Playlist all grant spins — save them and open in batches."},{n:4,title:"Buy Aftermarket, not Autoshow",body:"Green CT icons on the minimap sell secondhand, fully-tuned cars cheaper than new."}]},{id:"g-regions",title:"Complete the 10 regions",tag:"Exploration",shot:"https://i.ytimg.com/vi/dj2PkwfrRP0/maxresdefault.jpg",lead:"See everything Horizon Japan has to offer.",steps:[{n:1,title:"Drive, don't fast-travel",body:"Explore first to fill the map; you can blink to visited spots later. Stamp every region."},{n:2,title:"Clear PR stunts per region",body:"Each area has its own Speed Zones, Danger Signs and Drift Zones — great for accolades and spins."},{n:3,title:"Collect mascots",body:"Drive through the scattered mascots for credits as you go."},{n:4,title:"Photograph landmarks",body:"Landmark shots complete the Collection Journal and stack Discover Japan stamps."}]},{id:"g-estate",title:"Build the Estate",tag:"Property",shot:"https://i.ytimg.com/vi/H1qlPZMfmiU/maxresdefault.jpg",lead:"Your own mountainside base in rural Japan [WIKI].",steps:[{n:1,title:"Unlock it",body:"The Estate becomes available as you progress the festival in rural Japan."},{n:2,title:"Build & decorate",body:"Place buildings and style the grounds to taste — it's your personal festival hub."},{n:3,title:"Collect daily payouts",body:"Check the My Horizon message center for daily credit payouts from your property."}]}]},database:{intro:"Every car on this site, in one sortable table. Search by name, filter by discipline, or click a column to sort. Data is drawn from the Cars list — 550+ total at launch [WIKI]; this is a curated slice.",note:"Tip: click any column header to sort. Combine the search box with a discipline chip to narrow fast."},platforms:{intro:"Forza Horizon 6 is a current-gen title — no last-gen Xbox One disc build, and no native iOS/Android app. Pick your storefront below; the PC specs table shows what your rig needs.",stores:[{name:"Xbox Series X|S",kind:"Console",status:"Available",date:"May 19, 2026",note:"Disc & digital · day one on Game Pass Ultimate"},{name:"Steam",kind:"PC",status:"Available",date:"May 19, 2026",note:"Windows PC · day one on PC Game Pass"},{name:"Microsoft Store",kind:"PC",status:"Available",date:"May 19, 2026",note:"Windows PC (Xbox app) · PC Game Pass"},{name:"Xbox Cloud Gaming",kind:"Cloud",status:"Available",date:"May 19, 2026",note:"Stream on Xbox One, phone, tablet or browser via Game Pass Ultimate"},{name:"PlayStation 5",kind:"Console",status:"Delayed — date TBC",date:"TBC (2027 at the earliest)",note:"Standalone purchase · cross-save with Xbox & Steam. Not expected in 2026 per The Verge / IGN (Aug 27, 2026); not officially confirmed by Microsoft. Updated Aug 31, 2026."}],mobileNote:"There is no Forza Horizon 6 app on the App Store or Google Play. On phones and tablets the game is playable only through Xbox Cloud Gaming (Game Pass Ultimate) inside the Xbox app or a mobile browser — it is streamed, not installed.",requirements:{size:"167 GB (SSD required)",tiers:[{tier:"Minimum",goal:"1080p · 60 FPS · Low",os:"Windows 10 22H2 (19045) or 11",cpu:"Intel Core i5-8400 / AMD Ryzen 5 1600",ram:"16 GB",gpu:"NVIDIA GTX 1650 / AMD RX 6500 XT / Intel Arc A380",dx:"12",storage:"167 GB SSD"},{tier:"Recommended",goal:"1440p · 60 FPS · High",os:"Windows 10 22H2 or 11",cpu:"Intel Core i5-12400F / AMD Ryzen 5 5600X",ram:"16 GB",gpu:"NVIDIA RTX 3060 Ti / AMD RX 6700 XT / Intel Arc A580",dx:"12",storage:"167 GB SSD"},{tier:"Extreme (4K)",goal:"4K · 60 FPS · Ultra",os:"Windows 10/11 22H2 or newer",cpu:"Intel Core i7-12700K / AMD Ryzen 7 7700X",ram:"24 GB",gpu:"NVIDIA RTX 4070 Ti / AMD RX 7900 XT",dx:"12",storage:"NVMe SSD"},{tier:"Extreme (RT)",goal:"4K · 60 FPS · Ultra + Ray Tracing",os:"Windows 10/11 22H2 or newer",cpu:"Intel Core i7-12700K / AMD Ryzen 7 7700X",ram:"32 GB",gpu:"NVIDIA RTX 5070 Ti / AMD RX 9070 XT",dx:"12",storage:"NVMe SSD"}],features:["Uncapped frame rate on PC","NVIDIA DLSS 4 · AMD FSR 4 · Intel XeSS 2.1","Ray-traced reflections & global illumination","Ultrawide monitor support","Steam Deck & ROG Ally verified","Controller & steering-wheel support"],console:"Xbox Series X|S: Quality mode 30 FPS / 4K · Performance mode 60 FPS"}},faq:[{cat:"Release & platforms",items:[{q:"When did Forza Horizon 6 come out?",a:"Worldwide launch was May 19, 2026 on Windows and Xbox Series X/S [WIKI]. Players with the Premium Edition got early access from May 15, 2026 [WIKI]."},{q:"Is Forza Horizon 6 coming to PlayStation 5?",a:'Yes — but not on the original schedule. Wikipedia lists a planned PS5 version, and on August 27, 2026 Tom Warren of The Verge said he does not expect it on PS5 in 2026, with IGN reporting the same from its own sources. Warren stressed the port is "definitely still releasing" — delayed, not cancelled. Status: delayed, date TBC (2027 at the earliest per those reports). Microsoft and Playground Games have not issued an official statement or a revised date. It is expected as a standalone purchase with cross-save across Xbox and Steam. Last checked: August 31, 2026.'},{q:"Is it on Game Pass?",a:"Yes. Xbox Series X|S launched day one on Game Pass Ultimate, and both PC storefronts (Steam and the Microsoft Store) launched day one on PC Game Pass. The game is also playable through Xbox Cloud Gaming."},{q:"Can I play it on Xbox One or on my phone?",a:"There is no last-gen Xbox One build and no native iOS or Android app. On Xbox One, phones, tablets or a browser you can stream the game through Xbox Cloud Gaming with Game Pass Ultimate — it is streamed, not installed."},{q:"How big is the install, and what PC do I need?",a:"The install is 167 GB and an SSD is required. Minimum targets 1080p/60 at Low: Windows 10 22H2 or 11, an Intel Core i5-8400 or Ryzen 5 1600, 16 GB RAM, and a GTX 1650 / RX 6500 XT / Arc A380. Recommended targets 1440p/60 at High: an i5-12400F or Ryzen 5 5600X with an RTX 3060 Ti / RX 6700 XT / Arc A580."}]},{cat:"Cars & garages",items:[{q:"How many cars are in Forza Horizon 6?",a:'Two numbers, and the gap between them is the point. Forza Horizon 6 launched with 550+ cars on May 19, 2026 [WIKI]. The live roster is bigger now: we counted 636 cars in the official Forza car list table (forza.net/fh6cars), whose own header reads "Updated 13 August 2026". That 636 breaks down as 597 base-roster cars plus 39 add-on cars — 16 Car Pass, 8 Time Attack Car Pack, 5 Welcome Pack, 4 Italian Passion Car Pack, 3 VIP, 2 Partnership DLC and 1 preorder bonus. Other outlets quote different totals (618 is the late-May figure; some community lists say 607 or 642) — we publish the number we can reproduce from the official table, and the date it was counted.'},{q:"Is the Italian Passion Car Pack part of the Car Pass?",a:"No. The Italian Passion Car Pack (July 14, 2026) is a standalone $4.99 add-on. It includes the 2025 Ferrari F80, 1967 Ferrari 275 GTB4 Spider, 2021 Alfa Romeo Giulia GTAm and 1990 Alfa Romeo SE 048SP, and it comes free with the Premium Edition or Premium Upgrade. Buying the Car Pass does not get you these four cars."},{q:"What are the 8 garages for — and are they the same as the 8 houses?",a:"No, they are two different sets of 8. The 8 Garages are Wikipedia-confirmed [WIKI]: each doubles as a free fast-travel point and a car-display showroom with customisable, community-downloadable interiors. The 8 buyable player houses are a separate, community-sourced list with perks. Wikipedia confirms only one property outright — The Estate. Unlocking all 8 garages early makes crossing the large map much quicker."},{q:"Do you publish the garage locations?",a:'Not yet — official garage coordinates are not published, so every garage in our data is marked "Location TBC". You can use the Garage map & tracker on the Houses page to tag which region you found each one in; that data is yours and is saved in this browser only.'},{q:"How many Barn Finds and Treasure Cars are there, and what are they?",a:"15 Barn Finds and 9 Treasure Cars, all free. Barn Finds are gated behind the seven Discover Japan stamp tiers and need real-time restoration; the roster runs from the 2005 Honda NSX-R GT (Visitor tier) to the 1991 Mazda 787B and 1983 Nissan #11 Tomica Skyline (Master Explorer tier). Treasure Cars need no progression and no restoration — just a photo clue — and they include the 1991 Nissan Figaro in Tokyo City and the 2005 Ford GT in Nangan. Full rosters with region and landmark pointers are on the Barn Finds and Treasure Cars pages."}]},{cat:"Houses & the Estate",items:[{q:"What is The Estate?",a:"The Estate (Yashiki House) is your customisable mountainside property in rural Japan. Clear the 19 objects blocking the land and pay 10,000 Cr, and it becomes a permanent plot that friends can visit, with up to 12 players co-creating through Horizon Collab."},{q:"How do I unlock the houses?",a:"Houses are gated by Discover Japan stamps and credits. Mei's House is free and auto-unlocks after the tutorial with the Yellow stamp; the Tokyo House costs 3,000,000 Cr (free with VIP); the Vision House needs the Gold stamp (Master Explorer)."},{q:"What can I build at The Estate?",a:"Nine categories, powered by an upgraded EventLab toolset: the main house, a garage wing with up to 50 display slots, a workshop, a viewing deck, driveways and paths, gardens and landscaping, decorative items, and seasonal changes that transform the plot with Japan's seasons."}]},{cat:"Progression & live content",items:[{q:"What is the Festival Playlist?",a:"It is the live content backbone. A new season drops each week across a four-week Series, handing out exclusive cars, credits and accolades for daily and weekly challenges. We list reward types only — never a specific car we cannot verify."},{q:"What is Legend Island?",a:"A special area unlocked with the Gold Wristband, featuring unique challenges, exclusive events, and a second Horizon Festival [WIKI]."},{q:"How many players can race together?",a:"The Eliminator battle-royale mode supports up to 72 players [WIKI]."}]},{cat:"The world",items:[{q:"Where is the game set?",a:"A fictionalised Japan — the largest open-world map the series has ever built [WIKI]. Confirmed areas include Tokyo, Legend Island, rural Japan and Mount Fuji as a backdrop; community guides report the full map spans around ten regions."},{q:"What should I do first?",a:"Run the Horizon Qualifiers and the Horizon Invitational for your first wristband, pick a starter that matches your style, don't blow credits at the Autoshow, and unlock garages as fast-travel points as you explore. The 14-step Beginner's Guide walks through the whole path."}]}]};